"""Explicit paths for the packaged desktop application; no import-time writes."""
import os
import sys
from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True)
class RuntimePaths:
    resources: Path
    user_data: Path

    @property
    def catalog(self):
        return self.resources / "config" / "applications"

    @property
    def overrides(self):
        return self.user_data / "config" / "local_overrides.json"

    @property
    def state(self):
        return self.user_data / "output" / "desktop-state.json"

    @property
    def history(self):
        return self.user_data / "output" / "history.sqlite3"

    @property
    def reports(self):
        return self.user_data / "output" / "reports"


def packaged_paths():
    """Resolve paths only. Startup/provisioning creates directories separately."""
    if not getattr(sys, "frozen", False):
        raise RuntimeError("Packaged paths require a frozen application")
    bundle = getattr(sys, "_MEIPASS", None)
    profile = os.environ.get("LOCALAPPDATA", "")
    if not bundle or not Path(bundle).is_absolute():
        raise RuntimeError("Packaged resources are unavailable")
    if not profile or not Path(profile).is_absolute():
        raise RuntimeError("Persistent user storage is unavailable")
    return RuntimePaths(Path(bundle), Path(profile) / "AppHealthChecker")
